-- DEMO ONLY. Execute on a separate TEST D1 database, never production.
-- All fake students marked source=demo_v5 and names suffixed 【演示】.
-- Campus = first existing campus. Run only after the initial admin setup.
INSERT OR IGNORE INTO enrollment(campus_id,student_id,class_group_id,status) SELECT s.campus_id,s.id,g.id,'active' FROM student s JOIN class_group g ON g.campus_id=s.campus_id WHERE s.source='demo_v5' AND s.name='小鹿【演示】' AND g.name='【演示】周六素描班';
